python3 << 'EOF'
import numpy as np
lines = open('build/guess.xyz').read().splitlines()
n = int(lines[0])
els, coords = [], []
for ln in lines[2:2+n]:
    p = ln.split()
    els.append(p[0]); coords.append([float(p[1]),float(p[2]),float(p[3])])
coords = np.array(coords)
# find suspiciously close pairs
vdw = {'H':1.2,'C':1.7,'N':1.55,'Si':2.1,'Cr':2.0}
bad = []
for i in range(n):
    for j in range(i+1, n):
        d = np.linalg.norm(coords[i]-coords[j])
        # exclude genuine bonds (they'll be < sum vdw anyway); just flag very short
        if d < 1.0:
            bad.append((i,els[i],j,els[j],round(d,3)))
print("very short contacts (<1.0 A):", bad)
# check H...H < 1.5 (could be ok, but list worst)
hh = []
for i in range(n):
    for j in range(i+1, n):
        if els[i]=='H' and els[j]=='H':
            d = np.linalg.norm(coords[i]-coords[j])
            if d < 1.6: hh.append(round(d,2))
print("num H...H < 1.6:", len(hh), sorted(hh)[:10])
EOF
